UPDATE sys_job_cluster
   SET sys_job_cluster_lease_until_ms = (UNIX_TIMESTAMP(NOW(3)) + #{leaseSeconds}) * 1000,
       sys_job_cluster_version = sys_job_cluster_version + 1
 WHERE sys_job_cluster_id = #{group}
   AND sys_job_cluster_leader_node = #{nodeId}

UPDATE sys_job_cluster
   SET sys_job_cluster_leader_node = NULL,
       sys_job_cluster_lease_until_ms = 0,
       sys_job_cluster_version = sys_job_cluster_version + 1
 WHERE sys_job_cluster_id = #{group}
   AND sys_job_cluster_leader_node = #{nodeId}
